function normalizeMediaKey(s: string): string {
  return s
    .replace(/ø/gi, 'o')
    .replace(/đ/gi, 'd')
    .replace(/ı/gi, 'i')
    .replace(/ß/gi, 'ss')
    .replace(/ł/gi, 'l')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9 ]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

export function getClubBadgeUrl(opts: { clubId?: string; name?: string; shortName?: string }): string | null {
  if (opts.clubId && AVAILABLE_BADGE_IDS.has(opts.clubId)) {
    return `/media/badges/${opts.clubId}.png`;
  }
  if (opts.clubId && CLUB_FOTMOB_BADGE_IDS[opts.clubId]) {
    return `https://images.fotmob.com/image_resources/logo/teamlogo/${CLUB_FOTMOB_BADGE_IDS[opts.clubId]}.png`;
  }
  if (opts.name) {
    const byName = CLUB_NAME_TO_BADGE_ID[normalizeMediaKey(opts.name)];
    if (byName && AVAILABLE_BADGE_IDS.has(byName)) {
      return `/media/badges/${byName}.png`;
    }
    if (byName && CLUB_FOTMOB_BADGE_IDS[byName]) {
      return `https://images.fotmob.com/image_resources/logo/teamlogo/${CLUB_FOTMOB_BADGE_IDS[byName]}.png`;
    }
  }
  if (opts.shortName) {
    const byShort = CLUB_SHORT_TO_BADGE_ID[opts.shortName.toUpperCase()];
    if (byShort && AVAILABLE_BADGE_IDS.has(byShort)) {
      return `/media/badges/${byShort}.png`;
    }
    if (byShort && CLUB_FOTMOB_BADGE_IDS[byShort]) {
      return `https://images.fotmob.com/image_resources/logo/teamlogo/${CLUB_FOTMOB_BADGE_IDS[byShort]}.png`;
    }
  }
  return null;
}

export function getPlayerPhotoUrl(opts: { playerId?: string; name?: string }): string | null {
  if (opts.name) {
    const key = normalizeMediaKey(opts.name);
    const byName = PLAYER_NAME_TO_PHOTO_ID[key];
    if (byName && AVAILABLE_PLAYER_PHOTO_IDS.has(byName)) {
      return `/media/players/${byName}.png`;
    }
    const fmId = PLAYER_FOTMOB_PHOTO_IDS[key];
    if (fmId) {
      return `https://images.fotmob.com/image_resources/playerimages/${fmId}.png`;
    }
    return null;
  }
  if (opts.playerId && AVAILABLE_PLAYER_PHOTO_IDS.has(opts.playerId)) {
    return `/media/players/${opts.playerId}.png`;
  }
  return null;
}
